<?php
namespace Tests\Feature;
use App\Models\{User,Apprentice,TrainingSession,LearningTask,SmartAction};
use App\Support\ApprenticeCalendar as C;
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{Mail,Http};
use Tests\TestCase;
class ApprenticeCalendarTest extends TestCase
{
 use LazilyRefreshDatabase;
 private function f():array{$this->travelTo(now()->setDate(2026,11,15)->setTime(10,0));$u=User::factory()->create(['role'=>'apprentice']);$a=Apprentice::factory()->create(['user_id'=>$u->id]);$admin=User::factory()->create(['role'=>'admin']);return compact('u','a','admin');}
 private function data(array $f):array{return C::capture($f['u'],'2026-11-15','2026-12-15');}
 public function test_own_roster_includes_saved_sessions_but_not_other_apprentices():void{$f=$this->f();TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'name'=>'OWN-SESSION-46','members'=>[$f['a']->id],'session_date'=>'2026-11-20','start_time'=>'09:00','end_time'=>'10:00']);TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'name'=>'OTHER-SESSION-46','members'=>[],'session_date'=>'2026-11-20']);$this->actingAs($f['u'])->get('/my-calendar')->assertOk()->assertSee('OWN-SESSION-46')->assertDontSee('OTHER-SESSION-46');}
 public function test_task_deadline_and_apprentice_action_are_distinct_from_appointment():void{$f=$this->f();LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'due_date'=>'2026-11-20','template'=>['kind'=>'task'],'title'=>'Own task']);SmartAction::factory()->create(['apprentice_id'=>$f['a']->id,'created_by'=>$f['admin']->id,'owner'=>'Apprentice','due_date'=>'2026-11-21','title'=>'Own agreed action']);$k=array_column($this->data($f)['events'],'kind');$this->assertContains('Task deadline',$k);$this->assertContains('Agreed action deadline',$k);$this->assertNotContains('Review appointment',$k);}
 public function test_pending_content_and_cross_profile_action_link_are_withheld():void{$f=$this->f();LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'due_date'=>'2026-11-20','template'=>['kind'=>'source-pending']]);$outside=LearningTask::factory()->create(['due_date'=>'2026-11-20']);SmartAction::factory()->create(['apprentice_id'=>$f['a']->id,'created_by'=>$f['admin']->id,'learning_task_id'=>$outside->id,'owner'=>'Apprentice']);$d=$this->data($f);$this->assertSame([],$d['events']);$this->assertSame(2,$d['source_checks']);}
 public function test_cancelled_rostered_session_is_labelled_and_exported_as_cancelled():void{$f=$this->f();$s=TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'members'=>[$f['a']->id],'session_date'=>'2026-11-20','start_time'=>'09:00','end_time'=>'10:00']);$s->forceFill(['state'=>'Cancelled'])->save();$ics=C::ics($this->data($f));$this->assertStringContainsString('STATUS:CANCELLED',$ics);}
 public function test_ics_uses_utc_timed_events_and_exclusive_all_day_end():void{$f=$this->f();TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'members'=>[$f['a']->id],'session_date'=>'2026-11-20','start_time'=>'09:00','end_time'=>'10:00']);LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'due_date'=>'2026-11-21','template'=>['kind'=>'task']]);$ics=C::ics($this->data($f));$this->assertStringContainsString('DTSTART:20261120T090000Z',$ics);$this->assertStringContainsString('DTSTART;VALUE=DATE:20261121',$ics);$this->assertStringContainsString('DTEND;VALUE=DATE:20261122',$ics);$this->assertStringNotContainsString('VALARM',$ics);}
 public function test_calendar_download_has_generic_titles_no_private_fields_and_folded_lines():void{$f=$this->f();$t=LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'due_date'=>'2026-11-21','title'=>'PRIVATE-TASK-TITLE-46','template'=>['kind'=>'task'],'answers'=>['a'=>'PRIVATE-ANSWER-46']]);$ics=C::ics($this->data($f));$this->assertStringNotContainsString('PRIVATE-TASK-TITLE-46',$ics);$this->assertStringNotContainsString('PRIVATE-ANSWER-46',$ics);foreach(explode("\r\n",$ics)as$line){$this->assertLessThanOrEqual(75,strlen($line));}$this->assertStringContainsString('SUMMARY:Task deadline',$ics);}
 public function test_stable_event_uid_and_source_sequence_are_repeatable():void{$f=$this->f();LearningTask::factory()->create(['apprentice_id'=>$f['a']->id,'due_date'=>'2026-11-21','template'=>['kind'=>'task']]);$a=$this->data($f);$b=$this->data($f);$this->assertSame($a['events'][0]['uid'],$b['events'][0]['uid']);$this->assertSame(1,$a['events'][0]['version']);}
 public function test_invalid_roster_is_not_shown_as_a_confirmed_event():void{$f=$this->f();TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'members'=>[$f['a']->id,$f['a']->id],'session_date'=>'2026-11-20','start_time'=>'09:00','end_time'=>'10:00']);$d=$this->data($f);$this->assertSame(1,$d['source_checks']);$this->assertSame([],$d['events']);}
 public function test_ics_route_is_private_and_does_not_send_or_write():void{$f=$this->f();Mail::fake();Http::fake();$this->actingAs($f['u'])->get('/my-calendar.ics')->assertOk()->assertHeader('Content-Type','text/calendar; charset=UTF-8')->assertHeader('Referrer-Policy','no-referrer');Mail::assertNothingSent();Http::assertNothingSent();$this->assertDatabaseCount('apprentice_alert_deliveries',0);}
 #[\PHPUnit\Framework\Attributes\TestWith(['admin'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['tutor'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['employer'])]
 public function test_calendar_is_not_a_staff_impersonation_route(string $role):void{$this->actingAs(User::factory()->create(['role'=>$role]))->get('/my-calendar')->assertForbidden();$this->get('/my-calendar.ics')->assertForbidden();}
 #[\PHPUnit\Framework\Attributes\TestWith(['from[]=2026-11-15'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['from=2026-11-15&to=2027-11-15'])]
 #[\PHPUnit\Framework\Attributes\TestWith(['from=2026-12-15&to=2026-11-15'])]
 public function test_invalid_periods_are_rejected(string $query):void{$f=$this->f();$this->actingAs($f['u'])->getJson('/my-calendar?'.$query)->assertUnprocessable();}
 public function test_missing_link_is_held_and_no_calendar_is_guessed():void{$u=User::factory()->create(['role'=>'apprentice']);$this->actingAs($u)->get('/my-calendar')->assertStatus(409);}
 public function test_only_current_published_review_parties_appear_not_drafts_or_stale_parties():void{
  $f=$this->f();$employer=User::factory()->create(['role'=>'employer']);$tutor=User::factory()->create(['role'=>'tutor']);$e=\App\Models\Employer::factory()->create();$p=\App\Models\Programme::factory()->create();$f['a']->update(['email'=>$f['u']->email,'tutor_id'=>$tutor->id,'employer_id'=>$e->id,'programme_id'=>$p->id]);$g=\App\Support\EmployerActions::grant($f['admin'],1,$f['a'],['user_id'=>$employer->id,'version'=>0,'identity_reference'=>'Fictional authority reference']);$d=['grant_id'=>$g->id,'host_id'=>$tutor->id,'date'=>'2026-11-20','start'=>'10:00','end'=>'11:00','mode'=>'Training centre','place'=>'PRIVATE-PLACE-46'];$appt=\App\Support\ReviewAppointments::save($f['admin'],1,$f['a'],null,0,(string)\Illuminate\Support\Str::uuid(),$d);$this->assertNotContains('Review appointment',array_column($this->data($f)['events'],'kind'));\App\Support\ReviewAppointments::publish($f['admin'],1,$appt,1);$capture=$this->data($f);$this->assertContains('Review appointment',array_column($capture['events'],'kind'));$this->assertStringNotContainsString('PRIVATE-PLACE-46',C::ics($capture));$f['a']->update(['tutor_id'=>User::factory()->create(['role'=>'tutor'])->id]);$this->assertNotContains('Review appointment',array_column($this->data($f)['events'],'kind'));
 }
 public function test_summer_training_time_is_exported_as_utc_without_changing_local_time():void{$f=$this->f();TrainingSession::factory()->create(['created_by'=>$f['admin']->id,'members'=>[$f['a']->id],'session_date'=>'2027-06-01','start_time'=>'09:00','end_time'=>'10:00']);$d=C::capture($f['u'],'2027-06-01','2027-06-07');$this->assertStringContainsString('DTSTART:20270601T080000Z',C::ics($d));}

}
